// Updated 1790752638920
/**
 * ดึงรายการกล้อง CCTV ตรวจจับสถานการณ์น้ำท่วมและสภาพจราจร Real-time
 */
function getCctvCameras() {
  try {
    const data = getRealtimeFloodMonitoringData();
    return data && data.cctvCameras ? data.cctvCameras : [];
  } catch (err) {
    return [];
  }
}

/**
 * ดึงรายงานสถานการณ์น้ำท่วมขังบนผิวถนนตามมาตรฐาน DDS กทม.
 */
function getRoadFloodReports() {
  try {
    const data = getRealtimeFloodMonitoringData();
    return data && data.roadFloodReports ? data.roadFloodReports : [];
  } catch (err) {
    return [];
  }
}

/**
 * ดึงภาพถ่ายล่าสุดจากกล้อง CCTV สดของ กทม. ผ่านเซิร์ฟเวอร์
 */
function getCctvCameraSnapshot(snapId) {
  if (!snapId) return null;
  try {
    const url = 'https:' + '/' + '/world.tehx.dyndns.info/api/snap?id=' + encodeURIComponent(snapId) + '&w=480';
    const res = UrlFetchApp.fetch(url, {
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
        'Referer': 'https:' + '/' + '/world.tehx.dyndns.info/flood'
      },
      muteHttpExceptions: true
    });
    if (res.getResponseCode() === 200) {
      return 'data:image/jpeg;base64,' + Utilities.base64Encode(res.getContent());
    }
  } catch (err) {
    Logger.log('getCctvCameraSnapshot error: ' + err);
  }
  return null;
}

